def find_maximal_frames(grid):
    """Find non-overlapping maximal rectangular frames (single-cell border)."""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    frames = []
    visited_cells = set()

    for r1 in range(rows - 3):
        for c1 in range(cols - 3):
            # Check for frame starting at (r1, c1)
            frame_size = 4  # Minimum 4x4 for interior

            for frame_size in range(max(4, min(rows - r1, cols - c1)), min(rows - r1 + 1, cols - c1 + 1)):
                r2 = r1 + frame_size - 1
                c2 = c1 + frame_size - 1

                if r2 >= rows or c2 >= cols:
                    continue

                # Check if this is a valid frame: uniform border, uniform interior
                border_cells = []
                has_non_frame_color = False

                # Check top and bottom borders
                r_top, r_bot = r1, r2
                for r in [r1, r2]:
                    for c in range(c1, c2 + 1):
                        if grid[r][c] not in frame_cells:
                            has_non_frame_color = True
                            break
                    if has_non_frame_color:
                        break

                # Actually simpler: check if all border cells have same color
                # and interior cells are UNIFORM (all same color)

                # Check uniform border
                border_colors = set()
                for r in [r1, r2]:
                    for c in range(c1, c2 + 1):
                        border_colors.add(grid[r][c])
                for c in range(c1, c2 + 1):
                    for r in [r1, r2]:
                        border_colors.add(grid[r][c])
                for r in range(r1 + 1, r2):
                    for c in range(c1, c2 + 1):
                        border_colors.add(grid[r][c])

                border_empty = all(grid[r][c] == 0 for r in range(r1, r2+1) for c in range(c1, c2+1))

                if border_empty:
                    continue

                # Find interior color histogram
                interior_cells = [(r, c) for r in range(r1+1, r2) for c in range(c1+1, c2) if grid[r][c] != 0]

                if not interior_cells:
                    continue  # Empty interior, skip

                interior_color = interior_cells[0][0]
                if all(grid[r][c] == interior_color for r, c in interior_cells):
                    # Valid uniform interior frame
                    frames.append((r1, c1, r2, c2))

    return frames

