                    for c in range(c1, c2 + 1):
                        border_colors.add(grid[r1][c])
                        border_colors.add(grid[r2][c])
                    for r in range(r1 + 1, r2):
                        border_colors.add(grid[r][c1])
                        border_colors.add(grid[r][c2])

